// Package sessions stores API sessions in Postgres: the session.StorageProvider of the OSS API, scoped to the
// tenant of each call. Session ids are generated by the database and unique across tenants.
package sessions

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/jmoiron/sqlx"

	"github.com/pohcee/procy-server/server/api/session"

	"github.com/pohcee/procy-server/server/storage/postgres"
)

// Store is a session.StorageProvider on Postgres.
type Store struct {
	db *sqlx.DB
}

var _ session.StorageProvider = (*Store)(nil)

// New returns a Store on db (migrated).
func New(db *sqlx.DB) *Store { return &Store{db: db} }

// Close does nothing: the database is shared and closed by its owner.
func (s *Store) Close() error { return nil }

const columns = "session_id, tenant_id, expires_at, username, last_access_at, " +
	"coalesce(user_agent, '') AS user_agent, coalesce(ip_address, '') AS ip_address"

// GetAll returns the sessions that have not expired (by the clock of this process, as the OSS provider).
func (s *Store) GetAll(ctx context.Context) ([]session.APISession, error) {
	tid, err := postgres.TenantOf(ctx)
	if err != nil {
		return nil, err
	}
	var out []session.APISession
	err = postgres.InTenant(ctx, s.db, func(tx *sqlx.Tx) error {
		return tx.SelectContext(ctx, &out, "SELECT "+columns+" FROM api_sessions WHERE tenant_id = $1 AND expires_at >= $2", string(tid), time.Now())
	})
	if err != nil {
		return nil, fmt.Errorf("unable to get api sessions from DB: %w", err)
	}
	return out, nil
}

func (s *Store) Get(ctx context.Context, sessionID int64) (bool, session.APISession, error) {
	tid, err := postgres.TenantOf(ctx)
	if err != nil {
		return false, session.APISession{}, err
	}
	var out session.APISession
	found := false
	err = postgres.InTenant(ctx, s.db, func(tx *sqlx.Tx) error {
		err := tx.GetContext(ctx, &out, "SELECT "+columns+" FROM api_sessions WHERE tenant_id = $1 AND session_id = $2", string(tid), sessionID)
		if errors.Is(err, sql.ErrNoRows) {
			return nil
		}
		found = err == nil
		return err
	})
	if err != nil {
		return false, session.APISession{}, fmt.Errorf("unable to get api session from DB by token: %w", err)
	}
	if !found {
		return false, session.APISession{}, nil
	}
	return true, out, nil
}

// Save inserts a session without id and returns the new id, or updates the session with the id (in the context's
// tenant only; an id of another tenant changes nothing).
func (s *Store) Save(ctx context.Context, sess session.APISession) (int64, error) {
	tid, err := postgres.TenantOf(ctx)
	if err != nil {
		return -1, err
	}
	id := sess.SessionID
	err = postgres.InTenant(ctx, s.db, func(tx *sqlx.Tx) error {
		if id == 0 {
			return tx.GetContext(ctx, &id, `INSERT INTO api_sessions (tenant_id, expires_at, username, last_access_at, user_agent, ip_address)
				VALUES ($1, $2, $3, $4, $5, $6) RETURNING session_id`,
				string(tid), sess.ExpiresAt, sess.Username, sess.LastAccessAt, sess.UserAgent, sess.IPAddress)
		}
		res, err := tx.ExecContext(ctx, `UPDATE api_sessions SET expires_at = $3, username = $4, last_access_at = $5, user_agent = $6, ip_address = $7
			WHERE tenant_id = $1 AND session_id = $2`,
			string(tid), id, sess.ExpiresAt, sess.Username, sess.LastAccessAt, sess.UserAgent, sess.IPAddress)
		if err != nil {
			return err
		}
		if n, err := res.RowsAffected(); err != nil {
			return err
		} else if n == 0 {
			return fmt.Errorf("session %d: %w", id, session.ErrNotFound)
		}
		return nil
	})
	if err != nil {
		return -1, fmt.Errorf("unable to save api session: %w", err)
	}
	return id, nil
}

func (s *Store) Delete(ctx context.Context, sessionID int64) error {
	return s.exec(ctx, "unable to delete api session by token", "DELETE FROM api_sessions WHERE tenant_id = $1 AND session_id = $2", sessionID)
}

func (s *Store) DeleteExpired(ctx context.Context) error {
	return s.exec(ctx, "unable to delete expired api sessions", "DELETE FROM api_sessions WHERE tenant_id = $1 AND expires_at <= $2", time.Now())
}

func (s *Store) DeleteAllByUser(ctx context.Context, username string) error {
	return s.exec(ctx, "unable to delete api sessions of user", "DELETE FROM api_sessions WHERE tenant_id = $1 AND username = $2", username)
}

func (s *Store) DeleteByID(ctx context.Context, username string, sessionID int64) error {
	return s.exec(ctx, "unable to delete api session", "DELETE FROM api_sessions WHERE tenant_id = $1 AND username = $2 AND session_id = $3",
		username, sessionID)
}

// exec runs q with the context's tenant as $1 followed by args.
func (s *Store) exec(ctx context.Context, msg, q string, args ...any) error {
	tid, err := postgres.TenantOf(ctx)
	if err != nil {
		return err
	}
	err = postgres.InTenant(ctx, s.db, func(tx *sqlx.Tx) error {
		_, err := tx.ExecContext(ctx, q, append([]any{string(tid)}, args...)...)
		return err
	})
	if err != nil {
		return fmt.Errorf("%s: %w", msg, err)
	}
	return nil
}
